// Builds the Web client bundle from the ESM modules in client/src/.
// The Harness Web module loader loads one file that registers a lazy factory for this package id, so the bundle
// still ends in `window.__ModuleLoader__.load({ id, factory(require) { … } })` — only the inside changed: the
// modules are real ES modules (`client/src/index.js` is the entry, imports are explicit), esbuild bundles them to
// CommonJS so `require('react')` stays a call into the loader, and the banner/footer supply the `module`/`exports`
// shims the factory contract expects.
//
// esbuild is pinned exactly so `--check` can compare the generated bytes; a different esbuild version is a
// deliberate change. JSX compiles through `jsxFactory: 'h'`, which every module imports from `react.js`.
import { readFileSync, writeFileSync, readdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { createRequire } from 'node:module'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const sourceDir = join(root, 'client', 'src')
const outFile = join(root, 'client', 'index.js')
const mapFile = `${outFile}.map`
const PACKAGE = '@mystic7c/dsh-superagent-panel'

const require = createRequire(import.meta.url)
let esbuild
try {
  esbuild = require('esbuild')
} catch (error) {
  console.error('build-client needs esbuild: run `npm ci` in the repo root first.')
  console.error(error instanceof Error ? error.message : String(error))
  process.exit(2)
}

const files = readdirSync(sourceDir).filter(name => name.endsWith('.js') && !['index.js'].includes(name)).sort()
if (files.length === 0) throw new Error('client/src has no modules')
const entry = join(sourceDir, 'index.js')

const banner = `// Generated by scripts/build-client.mjs from client/src/index.js — do not edit by hand.
// Registers the Superagent management panel: sidebar icon in \`sidebar.panellist\` and the full
// management panel in the keyed \`main\` slot. Plain React only; data comes from the host half over
// same-origin \`/superagent/api\` routes. Bundled and minified by esbuild; read client/src and index.js.map.
window.__ModuleLoader__.load({
  id: ${JSON.stringify(PACKAGE)},
  factory(require) {
    const module = { exports: {} }
    const exports = module.exports
`
const footer = `
    return module.exports
  },
})
`

// A real bundle: the modules are ESM with explicit imports, and `react` stays external so the loader
// supplies it. `format: 'cjs'` plus the banner's `module`/`exports` shims keep the factory contract the
// loader expects, while `jsxFactory: 'h'` still points JSX at the shared `h` binding from react.js.
const result = esbuild.buildSync({
  entryPoints: [entry],
  outfile: outFile,
  bundle: true,
  format: 'cjs',
  platform: 'browser',
  target: 'es2022',
  external: ['react', 'react-dom', 'react/jsx-runtime'],
  loader: { '.js': 'jsx' },
  jsx: 'transform',
  jsxFactory: 'h',
  jsxFragment: 'React.Fragment',
  minify: true,
  legalComments: 'none',
  sourcemap: 'external',
  banner: { js: banner },
  footer: { js: footer },
  charset: 'utf8',
  write: false,
  logLevel: 'silent',
})
const jsFile = result.outputFiles.find(file => file.path.endsWith('.js'))
const mapFileOutput = result.outputFiles.find(file => file.path.endsWith('.map'))
if (!jsFile || !mapFileOutput) throw new Error('esbuild returned no js/map output')
const output = `${jsFile.text}//# sourceMappingURL=index.js.map\n`
const map = `${mapFileOutput.text.trimEnd()}\n`

if (process.argv.includes('--check')) {
  const current = (() => { try { return readFileSync(outFile, 'utf8') } catch { return undefined } })()
  const currentMap = (() => { try { return readFileSync(mapFile, 'utf8') } catch { return undefined } })()
  if (current !== output) {
    console.error('client/index.js is out of date; run `node scripts/build-client.mjs`')
    process.exit(1)
  }
  if (currentMap !== map) {
    console.error('client/index.js.map is out of date; run `node scripts/build-client.mjs`')
    process.exit(1)
  }
  console.log(`client/index.js is up to date (${files.length} modules, ${Buffer.byteLength(output)} bytes)`)
} else {
  writeFileSync(outFile, output)
  writeFileSync(mapFile, map)
  console.log(`wrote ${outFile} (${files.length} modules, ${Buffer.byteLength(output)} bytes)`)
}
